const BUSINESS_CONFIG = {
  businessName: 'Demo Business',
  language: 'Persian (Farsi) unless the customer writes in another language',
  services: 'General customer inquiries (replace with the real product/service list for this client)',
  handoffKeywords: ['شکایت', 'complaint', 'refund', 'مرجوعی', 'لغو', 'cancel', 'قانونی', 'lawyer'],
};
const CONFIDENCE_THRESHOLD = 0.6;

// Set this to the same random string you enter in the Meta App dashboard
// (WhatsApp > Configuration > Webhook > Verify Token). Move this to an n8n
// credential/environment variable for anything beyond a demo.
const VERIFY_TOKEN = 'REPLACE_WITH_YOUR_VERIFY_TOKEN';

const q = $input.first().json.query || {};
const mode = q['hub.mode'];
const token = q['hub.verify_token'];
const challenge = q['hub.challenge'];

if (mode === 'subscribe' && token === VERIFY_TOKEN) {
  return [{ json: { statusCode: 200, body: challenge } }];
}
return [{ json: { statusCode: 403, body: 'verification failed' } }];

/**
 * normalize.js
 * Turns a raw WhatsApp Cloud API webhook POST body into a flat list of
 * normalized "events" this workflow can act on.
 *
 * WhatsApp webhook shape (Cloud API, Meta):
 * {
 *   object: "whatsapp_business_account",
 *   entry: [{
 *     id: "<WABA id>",
 *     changes: [{
 *       field: "messages",
 *       value: {
 *         messaging_product: "whatsapp",
 *         metadata: { phone_number_id, display_phone_number },
 *         contacts: [{ profile: { name }, wa_id }],
 *         messages: [{ from, id, timestamp, type, text, image, ... }],
 *         statuses: [{ id, status, recipient_id, timestamp }]
 *       }
 *     }]
 *   }]
 * }
 *
 * Known real-world edge cases handled here (not happy-path-only):
 * - `messages` and `statuses` can both be present, or either can be absent.
 * - A single webhook call can carry more than one message (rare but allowed
 *   by the API, e.g. if delivery was delayed and Meta batches).
 * - `statuses` entries (sent/delivered/read/failed) are NOT user messages
 *   and must not be treated as one -- a naive workflow that reacts to any
 *   webhook hit will "reply" to its own delivery receipts.
 * - Meta redelivers the same webhook if your endpoint is slow or returns
 *   non-2xx, so the same message `id` can arrive more than once. Dedup is
 *   the caller's job (see dedupe.js) but this module exposes the id needed
 *   to do it.
 * - Non-text message types (image, audio, document, sticker, location,
 *   interactive button/list reply, unknown/unsupported) must not be run
 *   through a text-only AI prompt -- extract what's usable, flag the rest.
 * - `timestamp` is a unix-seconds value encoded as a STRING.
 * - Malformed/partial payloads (missing entry, empty changes, test pings
 *   from the Meta dashboard) must not throw.
 */

/**
 * @param {any} body - raw JSON body of the webhook POST
 * @returns {Array<object>} normalized events, each one of:
 *   { kind: 'message', id, from, timestamp, phoneNumberId, contactName, messageType, text, raw }
 *   { kind: 'status',  id, status, recipientId, timestamp }
 */
function normalizeWebhookBody(body) {
  const events = [];

  if (!body || typeof body !== 'object') return events;
  if (body.object !== 'whatsapp_business_account') return events;
  if (!Array.isArray(body.entry)) return events;

  for (const entry of body.entry) {
    const changes = Array.isArray(entry && entry.changes) ? entry.changes : [];
    for (const change of changes) {
      if (!change || change.field !== 'messages') continue;
      const value = change.value || {};
      const phoneNumberId =
        value.metadata && value.metadata.phone_number_id
          ? String(value.metadata.phone_number_id)
          : null;

      const contactsByWaId = {};
      if (Array.isArray(value.contacts)) {
        for (const c of value.contacts) {
          if (c && c.wa_id) {
            contactsByWaId[c.wa_id] = (c.profile && c.profile.name) || null;
          }
        }
      }

      if (Array.isArray(value.messages)) {
        for (const msg of value.messages) {
          if (!msg || !msg.id || !msg.from) continue; // malformed entry, skip
          events.push(normalizeSingleMessage(msg, phoneNumberId, contactsByWaId));
        }
      }

      if (Array.isArray(value.statuses)) {
        for (const st of value.statuses) {
          if (!st || !st.id) continue;
          events.push({
            kind: 'status',
            id: String(st.id),
            status: st.status || 'unknown',
            recipientId: st.recipient_id || null,
            timestamp: st.timestamp || null,
          });
        }
      }
    }
  }

  return events;
}

const SUPPORTED_TEXTLIKE_TYPES = new Set(['text', 'button', 'interactive']);

function normalizeSingleMessage(msg, phoneNumberId, contactsByWaId) {
  const base = {
    kind: 'message',
    id: String(msg.id),
    from: String(msg.from),
    timestamp: msg.timestamp || null,
    phoneNumberId,
    contactName: contactsByWaId[msg.from] || null,
    messageType: msg.type || 'unknown',
    text: null,
    raw: msg,
  };

  switch (msg.type) {
    case 'text':
      base.text = (msg.text && typeof msg.text.body === 'string') ? msg.text.body.trim() : '';
      break;
    case 'button':
      // reply to a template button
      base.text = (msg.button && msg.button.text) || '';
      break;
    case 'interactive': {
      const it = msg.interactive || {};
      if (it.type === 'button_reply' && it.button_reply) {
        base.text = it.button_reply.title || it.button_reply.id || '';
      } else if (it.type === 'list_reply' && it.list_reply) {
        base.text = it.list_reply.title || it.list_reply.id || '';
      } else {
        base.text = '';
      }
      break;
    }
    default:
      // image, audio, video, document, sticker, location, contacts, unknown...
      base.text = null;
      break;
  }

  base.isTextLike = SUPPORTED_TEXTLIKE_TYPES.has(msg.type) && !!base.text;
  return base;
}

/**
 * dedupe.js
 * WhatsApp Cloud API redelivers the same webhook when your endpoint is slow
 * or returns a non-2xx status. Without dedup, a slow AI call means the same
 * inbound message gets answered twice (or a human gets paged twice).
 *
 * In n8n this is backed by the workflow's static data
 * ($getWorkflowStaticData('global')), which n8n persists in its own
 * database per workflow. That's fine for a single-instance MVP; it is NOT
 * safe under horizontal scaling (multiple n8n workers) or huge volume,
 * because it round-trips the whole store on every read/write and has no
 * row-level locking. Documented in README as a known scaling limit.
 *
 * seenIds is a plain object map { [messageId]: timestampMs } so it is
 * JSON-serializable (a requirement for n8n static data).
 */

const DEFAULT_TTL_MS = 24 * 60 * 60 * 1000; // 24h: WhatsApp message ids don't repeat after that in practice

/**
 * @param {Record<string, number>} seenIds - mutated in place
 * @param {string} messageId
 * @param {number} nowMs
 * @param {number} ttlMs
 * @returns {boolean} true if this is a NEW message (caller should process it)
 */
function markAndCheck(seenIds, messageId, nowMs = Date.now(), ttlMs = DEFAULT_TTL_MS) {
  if (!messageId) return true; // nothing to dedup against; let it through

  // opportunistic cleanup so the object doesn't grow forever
  for (const id of Object.keys(seenIds)) {
    if (nowMs - seenIds[id] > ttlMs) delete seenIds[id];
  }

  if (Object.prototype.hasOwnProperty.call(seenIds, messageId)) {
    return false; // already processed -> duplicate delivery
  }
  seenIds[messageId] = nowMs;
  return true;
}

/**
 * router.js
 * Final decision layer: given the normalized event, the dedup result, the
 * session state and (if we got that far) the AI result, decide exactly one
 * action. This is kept separate from ai-agent.js so the "when do we shut up
 * and hand off to a human" policy is in one auditable place.
 *
 * Session shape (persisted externally -- see README for storage options):
 * {
 *   waId: string,
 *   state: 'bot' | 'human',       // 'human' = a person took over; bot stays silent
 *   history: [{ role: 'user'|'bot', text: string, ts: number }],
 *   lead: { name: string|null, intent: string|null },
 *   nonTextStreak: number,        // consecutive non-text messages with no usable text
 *   updatedAt: number
 * }
 */

const MAX_HISTORY_TURNS = 12; // keep prompts bounded; older context summarized by not being there
const NON_TEXT_HANDOFF_STREAK = 2; // 2 media-only messages in a row -> let a human look

function newSession(waId, now = Date.now()) {
  return {
    waId,
    state: 'bot',
    history: [],
    lead: { name: null, intent: null },
    nonTextStreak: 0,
    updatedAt: now,
  };
}

function pushHistory(session, role, text, now = Date.now()) {
  session.history.push({ role, text, ts: now });
  if (session.history.length > MAX_HISTORY_TURNS) {
    session.history = session.history.slice(-MAX_HISTORY_TURNS);
  }
  session.updatedAt = now;
}

/**
 * @param {object} event - normalized event from normalize.js (kind: 'message')
 * @param {object} session - session object (will be mutated)
 * @param {object|null} aiResult - result of ai-agent.parseAiResponse, or null
 *   if we haven't called the AI yet (e.g. non-text message, or already
 *   in human mode)
 * @returns {{ action: 'reply'|'handoff'|'ignore', replyText: string|null, reason: string }}
 */
function decide(event, session, aiResult) {
  if (session.state === 'human') {
    // A person already took this conversation over. The bot stays silent
    // until the human (via the CRM/sheet) flips the session back to 'bot'.
    // This is a deliberate product decision, not an oversight: an AI reply
    // arriving *after* a human already answered is confusing and looks
    // unprofessional to the customer.
    return { action: 'ignore', replyText: null, reason: 'session_owned_by_human' };
  }

  if (!event.isTextLike) {
    session.nonTextStreak = (session.nonTextStreak || 0) + 1;
    if (session.nonTextStreak >= NON_TEXT_HANDOFF_STREAK) {
      return {
        action: 'handoff',
        replyText: 'پیام شما دریافت شد؛ همکار ما به‌زودی به صورت شخصی پاسخ می‌دهد.',
        reason: 'repeated_non_text',
      };
    }
    return {
      action: 'reply',
      replyText: 'لطفاً درخواستتان را به صورت پیام متنی هم برایمان بنویسید تا بتوانیم دقیق پاسخ بدهیم 🙏',
      reason: 'non_text_message',
    };
  }

  session.nonTextStreak = 0;

  if (!aiResult) {
    // Should not happen if the caller wired things correctly, but never
    // send nothing and never crash -- fail toward a human.
    return { action: 'handoff', replyText: null, reason: 'missing_ai_result' };
  }

  if (aiResult.parseError) {
    return { action: 'handoff', replyText: null, reason: 'ai_response_unparseable' };
  }

  if (aiResult.handoff) {
    return {
      action: 'handoff',
      replyText: aiResult.reply || null, // if the model still produced a polite reply, send it before escalating
      reason: aiResult.confidence < 0.6 ? 'low_confidence' : 'model_requested_handoff',
    };
  }

  return { action: 'reply', replyText: aiResult.reply, reason: 'ai_answered' };
}

/**
 * ai-agent.js
 * Builds the prompt sent to the LLM and defensively parses its response.
 *
 * The model is instructed to return ONLY a JSON object. In practice LLMs
 * sometimes:
 *  - wrap JSON in ```json fences
 *  - add a sentence before/after the JSON
 *  - return invalid JSON (trailing comma, single quotes, truncated on
 *    length cutoff)
 *  - omit fields
 * None of those may crash the workflow or silently produce an empty reply
 * that gets sent to a real customer -- they must force a human handoff.
 */

const DEFAULT_CONFIDENCE_THRESHOLD = 0.6;

function buildSystemPrompt(businessConfig) {
  const { businessName, language, services, handoffKeywords } = businessConfig;
  return [
    `You are the first-line WhatsApp assistant for "${businessName}".`,
    `Reply in ${language || 'the language the customer wrote in'}.`,
    services ? `What this business offers: ${services}` : null,
    'Your job: answer simple questions, collect the lead\'s name and what they need, and know when you are out of your depth.',
    'Escalate to a human (set "handoff": true) whenever: the customer asks for a price/quote you are not certain of, asks something you cannot answer confidently, sounds angry or upset, explicitly asks for a human, or asks something unrelated to the business.',
    handoffKeywords && handoffKeywords.length
      ? `Always escalate immediately if the message contains any of these words: ${handoffKeywords.join(', ')}.`
      : null,
    'Respond with ONLY a single JSON object, no prose outside it, matching exactly this shape:',
    '{"reply": string, "confidence": number between 0 and 1, "handoff": boolean, "lead": {"name": string|null, "intent": string|null}}',
    '"confidence" is YOUR OWN estimate of how correct/safe "reply" is. Be honest and conservative: if unsure, use a low number and set handoff true.',
  ]
    .filter(Boolean)
    .join('\n');
}

function buildMessages(businessConfig, history, incomingText) {
  const messages = [{ role: 'system', content: buildSystemPrompt(businessConfig) }];
  for (const turn of history || []) {
    messages.push({ role: turn.role === 'bot' ? 'assistant' : 'user', content: turn.text });
  }
  messages.push({ role: 'user', content: incomingText });
  return messages;
}

/**
 * Extracts a JSON object from a raw LLM text response, tolerating common
 * wrapping mistakes (code fences, leading/trailing prose).
 */
function extractJsonObject(rawText) {
  if (typeof rawText !== 'string') return null;
  let s = rawText.trim();

  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) s = fenced[1].trim();

  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');
  if (first === -1 || last === -1 || last < first) return null;
  s = s.slice(first, last + 1);

  try {
    return JSON.parse(s);
  } catch (e) {
    return null;
  }
}

/**
 * @param {string} rawText - raw content string from the LLM API response
 * @param {number} confidenceThreshold
 * @returns {{ ok: boolean, reply: string|null, confidence: number, handoff: boolean,
 *             lead: {name: string|null, intent: string|null}, parseError: boolean }}
 */
function parseAiResponse(rawText, confidenceThreshold = DEFAULT_CONFIDENCE_THRESHOLD) {
  const parsed = extractJsonObject(rawText);

  if (!parsed || typeof parsed !== 'object') {
    return {
      ok: false,
      reply: null,
      confidence: 0,
      handoff: true,
      lead: { name: null, intent: null },
      parseError: true,
    };
  }

