  }

  if (aiResult.parseError) {
    return { action: 'handoff', replyText: null, reason: 'ai_response_unparseable' };
  }

  if (aiResult.handoff) {
    return {
      action: 'handoff',
      replyText: aiResult.reply || null, // if the model still produced a polite reply, send it before escalating
      reason: aiResult.confidence < 0.6 ? 'low_confidence' : 'model_requested_handoff',
    };
  }

  return { action: 'reply', replyText: aiResult.reply, reason: 'ai_answered' };
}

const CONFIDENCE_THRESHOLD = 0.6;

const staticData = $getWorkflowStaticData('global');
const prior = $('Normalize, Dedupe, Route').item.json;
const aiResponse = $json;

const rawText =
  aiResponse && aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message
    ? aiResponse.choices[0].message.content
    : null;

const aiResult = parseAiResponse(rawText, CONFIDENCE_THRESHOLD);
const session = staticData.sessions[prior.waId];

const decision = decide(prior.event, session, aiResult);

if (decision.action === 'handoff') {
  session.state = 'human';
}
if (decision.replyText) {
  pushHistory(session, 'bot', decision.replyText);
}

return {
  json: {
    waId: prior.waId,
    phoneNumberId: prior.phoneNumberId,
    contactName: prior.contactName,
    decision,
    aiResult,
  },
};
